function createItem(
  name: string,
  category: string,
  subcategory: string,
  width: number,
  height: number,
  color: string,
  icon: string
): FurnitureCatalogItem {
  return {
    id: generateId(),
    name,
    category,
    subcategory,
    width,
    height,
    color,
    icon
  }
}

